The Terraform configuration below creates an AWS Lightsail MySQL managed database. It configures:

- A Lightsail relational database using MySQL 8.0
- Daily automated backups between `16:00` and `16:30` UTC
- Maintenance operations, including potentially disruptive changes, on Tuesdays between `17:00` and `17:30` UTC
- A generated secure master password
- Required provider configuration with default values for all variables

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

provider "random" {}

variable "aws_region" {
  description = "AWS region where the Lightsail database will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail database."
  type        = string
  default     = "us-east-1a"
}

variable "database_name" {
  description = "The name of the Lightsail relational database resource."
  type        = string
  default     = "mysql-lightsail-db"
